import requests, re, numpy as np, pandas as pd, collections
import matplotlib.pyplot as plt
from matplotlib.colors import ListedColormap

# ---------- 1RGO contact frequencies ----------
rg=requests.get('https://files.rcsb.org/download/1RGO.pdb',timeout=120).text
aa3to1={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I',
'LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
BB={'P','OP1','OP2',"O5'","C5'","C4'","O4'","C3'","O3'","C2'","O2'","C1'"}
models=collections.defaultdict(list); cur=None
for l in rg.split('\n'):
    if l.startswith('MODEL'): cur=int(l.split()[1])
    elif l.startswith('ENDMDL'): cur=None
    elif cur and l.startswith('ATOM'):
        if (l[76:78].strip() or l[12:16].strip()[0])=='H': continue
        models[cur].append((l[21],int(l[22:26]),l[17:20].strip(),l[12:16].strip(),
                            float(l[30:38]),float(l[38:46]),float(l[46:54])))
N=len(models); cb=collections.Counter(); ca_=collections.Counter()
for at in models.values():
    P=[a for a in at if a[0]=='A']; R=[a for a in at if a[0]=='D']
    D=np.linalg.norm(np.array([a[4:7] for a in P])[:,None]-np.array([a[4:7] for a in R])[None],axis=2)
    ii,jj=np.where(D<4.0); sa=set(); sb=set()
    for i,j in zip(ii,jj):
        sa.add(P[i][1])
        if R[j][3] not in BB: sb.add(P[i][1])
    for x in sa: ca_[x]+=1
    for x in sb: cb[x]+=1
pres={a[1]:aa3to1[a[2]] for a in models[1] if a[0]=='A'}; nums=sorted(pres)

# ---------- sequence table ----------
ACC = {'TIS11d_Hs':'P47974','TTP_Hs':'P26651','POS1_Ce':'G5EF15','OMA1_Ce':'G5EC86','MEX1_Ce':'Q7JM77',
 'MEX5_Ce':'Q9XUB2','MEX6_Ce':'Q09436','Cbri_A8XEE2':'A8XEE2','Cbri_A0AAE9E5I7':'A0AAE9E5I7',
 'Cnig_A0A2G5VID8':'A0A2G5VID8','Crem_E3MGB7':'E3MGB7','Crem_A0A260YMZ3':'A0A260YMZ3',
 'Clat_A0A261C4R2':'A0A261C4R2','Cbre_G0NJK9':'G0NJK9','Cbre_G0NJL3':'G0NJL3','Cbov_A0A8S1F1E1':'A0A8S1F1E1'}
SEQ={n:''.join(requests.get(f'https://rest.uniprot.org/uniprotkb/{a}.fasta',timeout=30).text.split('\n')[1:]) for n,a in ACC.items()}
pat=re.compile(r'(?=(C.{7,12}C.{4,6}C.{2,4}H))')
def fingers(s):
    out={}
    for m in pat.finditer(s):
        g=m.group(1); st=m.start()+1
        mm=re.match(r'C(.{7,12}?)C(.{4,6}?)C(.{2,4}?)H$',g)
        if not mm: continue
        l1,l2,l3=map(len,mm.groups())
        out.setdefault(st,(st,st+1+l1,st+1+l1+1+l2,st+1+l1+1+l2+1+l3))
    return sorted(out.values())
ANCH={n:fingers(s) for n,s in SEQ.items()}
OFFS=[('C1',-6),('C1',-4),('C1',-3),('C1',-2),('C1',-1),('C1',0),('C1',1),('C1',2),
      ('C2',0),('C2',1),('C2',2),('C3',-1),('C3',0),('C3',1),('C3',2)]
AI={'C1':0,'C2':1,'C3':2}
T1={('C1',-6):153,('C1',-4):155,('C1',-3):156,('C1',-2):157,('C1',-1):158,('C1',0):159,('C1',1):160,('C1',2):161,
    ('C2',0):168,('C2',1):169,('C2',2):170,('C3',-1):173,('C3',0):174,('C3',1):175,('C3',2):176}
ROLE={('C1',-6):'bb',('C1',-4):'base U',('C1',-3):'base U',('C1',-2):'discriminator',('C1',-1):'base A',
 ('C1',0):'Zn',('C1',1):'base A',('C1',2):'base A/U',('C2',0):'Zn',('C2',1):'base U',
 ('C2',2):'stacking',('C3',-1):'contact',('C3',0):'Zn',('C3',1):'base',('C3',2):'stacking'}
labels=[];rows={n:[] for n in ACC}
for fi in (0,1):
    for o in OFFS:
        labels.append((f'ZF{fi+1}',f'{o[0]}{o[1]:+d}',T1[o]+38*fi,ROLE[o]))
        for n in ACC: rows[n].append(SEQ[n][ANCH[n][fi][AI[o[0]]]+o[1]-1])
FULL=pd.concat([pd.DataFrame(labels,columns=['finger','pos','TIS11d_num','role']),pd.DataFrame(rows)],axis=1)
POS=list(FULL.TIS11d_num)
ORDER=list(ACC.keys())
M=FULL[ORDER].values; ref=ORDER.index('MEX5_Ce'); same=(M==M[:,[ref]]).astype(int)

fig=plt.figure(figsize=(17,12))
gs=fig.add_gridspec(3,1,height_ratios=[1.0,2.3,0.85],hspace=0.55)
axA=fig.add_subplot(gs[0])
axA.bar(range(len(nums)),[ca_[n]/N for n in nums],color='#c9d6e8',label='any RNA atom within 4 A')
axA.bar(range(len(nums)),[cb[n]/N for n in nums],color='#2c5aa0',label='RNA base atom within 4 A')
axA.set_xticks(range(len(nums)))
axA.set_xticklabels([f'{pres[n]}{n}' for n in nums],rotation=90,fontsize=6)
for i,n in enumerate(nums):
    if n in POS:
        axA.get_xticklabels()[i].set_color('#b03030'); axA.get_xticklabels()[i].set_fontweight('bold')
axA.set_ylabel('fraction of 20 NMR models'); axA.set_ylim(0,1.15); axA.legend(fontsize=8,frameon=False)
axA.set_title("A. TIS11d TZF residues within 4 A of 5'-UUAUUUAUU-3' across the 20-model 1RGO ensemble.\n"
              "Red bold labels are the 30 positions carried into the cross-species comparison.",fontsize=10,loc='left')

axB=fig.add_subplot(gs[1])
axB.imshow(same.T,aspect='auto',cmap=ListedColormap(['#f3bfa4','#9ecfa0']),vmin=0,vmax=1)
for i in range(30):
    for j in range(len(ORDER)):
        axB.text(i,j,M[i,j],ha='center',va='center',fontsize=7.5)
axB.set_yticks(range(len(ORDER))); axB.set_yticklabels(ORDER,fontsize=8)
axB.set_xticks(range(30))
axB.set_xticklabels([f"{FULL['finger'][i]}\n{FULL['pos'][i]}\n{FULL['TIS11d_Hs'][i]}{FULL['TIS11d_num'][i]}" for i in range(30)],fontsize=6)
for i in range(30):
    if FULL['role'][i]=='discriminator': axB.axvline(i,color='#b03030',lw=1.6,alpha=0.85)
    if FULL['role'][i]=='stacking': axB.axvline(i,color='#2050a0',lw=1.0,ls=':',alpha=0.85)
axB.axhline(4.5,color='k',lw=0.9); axB.axhline(6.5,color='k',lw=0.9)
axB.set_title('B. Residue identity at the 30 RNA-contacting positions. Green = same as C. elegans MEX-5, orange = different.\n'
              'Solid red lines mark the C1-2 discriminator, dotted blue lines the intercalating aromatic positions.',fontsize=10,loc='left')

axC=fig.add_subplot(gs[2])
names=['MEX-6 ZF1','MEX-6 ZF2','MEX-6 tandem','MEX-5 ZF1','MEX-5 ZF2','MEX-5 tandem']
vals=[0.38,0.39,3.77,0.34,0.38,2.47]
axC.bar(names,vals,color=['#2c5aa0','#2c5aa0','#9aa7bd','#4a8f4a','#4a8f4a','#b5c9b5'])
for i,v in enumerate(vals): axC.text(i,v+0.08,f'{v:.2f}',ha='center',fontsize=9)
axC.set_ylabel('CA RMSD (A)'); axC.set_ylim(0,4.4)
axC.set_title('C. Anchor-matched superposition of the AlphaFold TZF models on RNA-bound TIS11d, 17 CA atoms per finger.\n'
              'Single fingers match closely; the tandem values reflect apo inter-finger orientation in the AlphaFold models.',fontsize=10,loc='left')
plt.show()
print('MEX-6 vs MEX-5 identity at the 30 positions:',(M[:,ORDER.index('MEX6_Ce')]==M[:,ref]).sum(),'/30')
